import sys
from collections import defaultdict

def solve_torpedoes():
    n, m = map(int, input().split())
    ships = [tuple(map(int, input().split())) for _ in range(m)]

    ship_positions = defaultdict(list)
    for x1, x2, y in ships:
        ship_positions[y].append((x1, x2))

    moves = ['-', '0', '+']
    directions = [-1, 0, 1]
    path = ['0'] * n

    current_x, current_y = 0, 0

    for i in range(n):
        possible = False
        for dx in directions:
            next_x, next_y = current_x + dx, current_y + 1
            if next_y not in ship_positions:
                path[i] = moves[directions.index(dx)]
                current_x, current_y = next_x, next_y
                possible = True
                break

        if not possible:
            for ship_x1, ship_x2 in ship_positions[current_y]:
                if ship_x1 <= current_x <= ship_x2:
                    return "impossible"

            next_x, next_y = current_x, current_y + 1
            path[i] = '0'
            current_x, current_y = next_x, next_y

    return ''.join(path)

if __name__ == "__main__":
