def avoid_ships(n, m, ships):
    # Initialize a grid to track whether a ship is present at a given (x, y)
    grid = {}
    for x1, x2, y in ships:
        for x in range(x1, x2 + 1):
            grid[(x, y)] = True

    # Directions the torpedo can move: (x, y)
    directions = [(0, 1), (-1, 1), (1, 1)]

    # Current position of the torpedo
    current_x, current_y = 0, 0
    path = ['0'] * n  # Initialize path with '0'

    for time in range(n):
        # Check if the current position is within a ship or hitting a ship
        if (current_x, current_y) in grid:
            return "impossible"

        # If no ship is found, determine the best direction to move
        best_direction = (0, 1)  # Default to moving forward
        for dx, dy in directions:
            new_x, new_y = current_x + dx, current_y + dy
            if (new_x, new_y) not in grid:
                best_direction = (dx, dy)
                break

        # Update the torpedo's position and record the path
        current_x += best_direction[0]
        current_y += best_direction[1]

        if best_direction == (-1, 1):
            path[time] = '-'
        elif best_direction == (1, 1):
            path[time] = '+'
        else:
            path[time] = '0'

    return ''.join(path)

